mapper.select:
select log_id, field_name, before_display_value, after_display_value, change_reason,
       operator_id, operator_name, operator_ip, create_time
from ry_business.ry_rental_order_edit_log
where tenant_id = #{tenantId}
  and member_id = #{merchantId}
  and order_id = #{orderId}
  and is_delete = 0
order by create_time desc, log_id desc

select warehouse_id as referenceId, warehouse_name as referenceName
from ry_business.ry_rental_warehouse
where tenant_id = #{tenantId}
  and member_id = #{merchantId}
  and is_delete = 0
  and warehouse_id in

    #{referenceId}

select channel_id as referenceId, channel_name as referenceName from ry_business.ry_rental_order_channel where is_delete = 0 and channel_id in
#{referenceId}
and ((scope_type = 1 and channel_type = 1) or (scope_type = 2 and tenant_id = #{tenantId} and member_id = #{merchantId}))

mapper.sql:
where o.tenant_id = #{tenantId} and o.member_id = #{merchantId} and o.is_delete = 0
and o.warehouse_id in
#{warehouseId}
and 1 = 0
and ( o.order_no like concat('%', #{query.keyword}, '%') or o.external_order_no like concat('%', #{query.keyword}, '%') or cch.channel_code like concat('%', #{query.keyword}, '%') or cch.channel_name like concat('%', #{query.keyword}, '%') or o.shop_name like concat('%', #{query.keyword}, '%') or o.customer_name like concat('%', #{query.keyword}, '%') or o.customer_phone like concat('%', #{query.keyword}, '%') or o.recipient_name like concat('%', #{query.keyword}, '%') or o.recipient_phone like concat('%', #{query.keyword}, '%') or c.customer_nickname like concat('%', #{query.keyword}, '%') or json_unquote(json_extract(o.package_details_json, '$.packageName')) like concat('%', #{query.keyword}, '%') or json_unquote(json_extract(o.package_details_json, '$.mainProduct.productName')) like concat('%', #{query.keyword}, '%') or json_unquote(json_extract(o.package_details_json, '$.mainProduct.modelName')) like concat('%', #{query.keyword}, '%') )
and o.order_status = #{query.status}
and o.order_status in (20, 25, 30)
and o.channel_id = #{query.channelId}
and o.warehouse_id = #{query.warehouseId}
and (o.time_effect_status = 1 or o.weather_risk_flag = 1 or o.order_status in (60, 65, 70) )
and o.return_due_time >= #{query.dateStart}
and o.arrival_date >= #{query.dateStart}
and o.lease_start_date >= #{query.dateStart}
and o.create_time >= #{query.dateStart}
and o.create_time >= #{query.dateStart}
and o.ship_due_time >= #{query.dateStart}
and o.return_due_time < date_add(#{query.dateEnd}, interval 1 day)
and o.arrival_date < date_add(#{query.dateEnd}, interval 1 day)
and o.lease_start_date < date_add(#{query.dateEnd}, interval 1 day)
and o.create_time < date_add(#{query.dateEnd}, interval 1 day)
and o.create_time < date_add(#{query.dateEnd}, interval 1 day)
and o.ship_due_time < date_add(#{query.dateEnd}, interval 1 day)
and o.ship_due_time >= current_date() and o.ship_due_time < date_add(current_date(), interval 1 day) and o.order_status <> 80
and o.return_due_time >= current_date() and o.return_due_time < date_add(current_date(), interval 1 day) and o.order_status <> 80
and o.arrival_date = current_date() and o.order_status not in (50, 80)
and o.arrival_date = date_add(current_date(), interval 1 day) and o.order_status not in (50, 80)
and o.create_time >= current_date() and o.create_time < date_add(current_date(), interval 1 day)
and o.order_status = 50 and o.update_time >= current_date() and o.update_time < date_add(current_date(), interval 1 day)

mapper.select:
select o.tenant_id, o.member_id, o.order_id, o.order_no, w.city as warehouse_city, recipient_history.city_code as recipient_city_code, recipient_history.district_code as recipient_district_code from ry_business.ry_rental_order o inner join ry_business.ry_rental_warehouse w on w.warehouse_id = o.warehouse_id and w.tenant_id = o.tenant_id and w.member_id = o.member_id and w.is_delete = 0 left join ( select h.tenant_id, h.member_id, h.order_no, h.city_code, h.district_code from ry_business.ry_rental_order_recipient_history h inner join ( select tenant_id, member_id, order_no, max(recipient_history_id) as recipient_history_id from ry_business.ry_rental_order_recipient_history where is_delete = 0 and used = 1 group by tenant_id, member_id, order_no ) latest_history on latest_history.recipient_history_id = h.recipient_history_id and latest_history.tenant_id = h.tenant_id and latest_history.member_id = h.member_id and latest_history.order_no = h.order_no where h.is_delete = 0 and h.used = 1 ) recipient_history on recipient_history.tenant_id = o.tenant_id and recipient_history.member_id = o.member_id and recipient_history.order_no = o.order_no where o.is_delete = 0 and o.ship_due_time >= #{shipDate} and o.ship_due_time < date_add(#{shipDate}, interval 1 day) and o.order_status in
#{orderStatus}
order by o.tenant_id, o.member_id, o.order_id

