  and is_delete = 0

mapper.update:
update ry_business.ry_rental_order
set pay_status = #{toStatus},
    version = version + 1,
    update_time = now()
where order_id = #{orderId}
  and tenant_id = #{tenantId}
  and member_id = #{merchantId}
  and pay_status = #{fromStatus}
  and order_status <> #{cancelledStatus}
  and is_delete = 0

update ry_business.ry_rental_order
set order_status = #{toStatus},
    version = version + 1,
    update_by = #{operatorId},
    update_time = now()
where order_id = #{orderId}
  and tenant_id = #{tenantId}
  and member_id = #{merchantId}
  and order_status = #{fromStatus}
  and is_delete = 0

update ry_business.ry_rental_order
set order_status = #{orderStatus},
    version = version + 1,
    update_by = #{operatorId},
    update_time = now()
where tenant_id = #{tenantId}
  and member_id = #{sourceMemberId}
  and order_id = #{sourceOrderId}
  and is_delete = 0
  and order_status <> #{orderStatus}

update ry_business.ry_rental_order_item
set product_id = coalesce((
        select package_item.product_id
        from ry_business.ry_rental_merchant_package_version package_version
        inner join ry_business.ry_rental_merchant_package_item package_item
            on package_item.package_version_id = package_version.package_version_id
           and package_item.item_role = 1
           and package_item.is_delete = 0
        where package_version.tenant_id = #{tenantId}
          and package_version.member_id = #{merchantId}
          and package_version.package_id = #{command.packageId}
          and package_version.version_status = 1
          and package_version.is_delete = 0
        order by package_version.version_no desc, package_item.package_item_id
        limit 1
    ), #{command.productId}),
    package_id = #{command.packageId},
    sn_id = #{command.snId},
    accessory_item_ids = #{command.accessoryItemIds},
    quantity = coalesce(#{command.quantity}, quantity),
    update_by = #{operatorId}, update_time = now()
where order_id = #{command.orderId}

  and order_item_id = #{command.orderItemId}

  and tenant_id = #{tenantId}
  and member_id = #{merchantId}
  and is_delete = 0

